def shell(slug, title, desc, body, schema="", noindex=False):
    links = "".join('<a href="%s"%s>%s</a>' % (h,' aria-current="page"' if h==slug else "",l)
                    for h,l in NAV)
    canon = DOMAIN + "/" + ("" if slug=="index.html" else slug)
